var l=[{title:`Válassz ismétlési tartományt`,text:`Válassz egy gyakorlatot, sorozatszámot és tartományt, például három sorozat 8–12 ismétlést. Kezdj olyan súllyal, amellyel egyenletes technikával eléred a tartomány alját, és néhány ismétlés tartalékban marad. A tartománynak nem kell 8–12-nek lennie. A célod és a gyakorlat szabja meg a határokat.`},{title:`Szerezd meg a terhelésnövelést`,text:`Először több jó ismétlést végezz ugyanazzal a súllyal több edzésen át. Amint minden sorozat eléri a tartomány tetejét a tervezett erőkifejtésen, add hozzá a legkisebb súlylépést, amid van. Az ismétléseid általában újra az alsó határ felé csökkennek, és a ciklus kezdődik elölről.`},{title:`Példa`,text:`1. hét: súlyzós evezés 12 kg-mal, 10, 9, 8 ismétlés. 2. hét: 11, 10, 9. 3. hét: 12, 12, 12 egyenletes kontrollal. 4. hét: próbálj 14 kg-ot 9, 8, 8 ismétléssel, ha jó formával bírod ezt az ugrást. Ezek a számok azt mutatják, hogyan alakulhat. Nem kell minden héten javulnod.`},{title:`Mikor igazítsd a szabályt`,text:`Egy nagy súlyugrás túl nehéz lehet, különösen kis izmoknál vagy korlátozott otthoni felszerelésnél. Ilyenkor maradj a jelenlegi terhelésnél, adj hozzá összes ismétlést, vagy válassz köztes változatot. Ha egy edzés szokatlanul fárasztónak érződik, ismételd az utolsó célt, és hagyd a haladást későbbre. A valódi fejlődés gyakran hullámzik.`},{title:`A TrainUp használata`,text:`A terved minden gyakorlathoz sorozatot és ismétlési célt ad, edzés közben pedig minden sorozatban rögzíted a befejezett ismétléseket. A TrainUp nem ír elő súlyokat, ezért te döntöd el, mikor adsz hozzá terhelést. Ha minden sorozatban eléred a tartomány tetejét, ellenőrizd az RPE-det és a technikádat, mielőtt nehezebbre váltasz.`}];var a=[{label:`2026-os ACSM állásfoglalás`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NSCA: biztonság és az ellenállásedzés alapjai`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Mayo Clinic: súlyzós edzés technikája (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var s={sections:l,sources:a};export{s as default,l as sections,a as sources};